bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
docker exec -i deploy-gaybbs-1 node -e '
const fs=require("node:fs"), assert=require("node:assert/strict");
const s=fs.readFileSync(0,"utf8");
const from=s.indexOf("function publicNavigationButton("),to=s.indexOf("function callbackStartlessPayload(",from);
assert.ok(from>=0&&to>from);
const fn=new Function("STARTLESS_BOT","STARTLESS_PREFIX","startlessPayload",s.slice(from,to)+";return publicNavigationButton;")("GayBBS_bot","gdm:",url=>url.endsWith("?start=search")?"search":null);
assert.equal(fn({text:"a",url:"https://t.me/GayBBS_bot?start=search"}).callback_data,"gdm:search");
assert.equal(fn({text:"a",url:"https://t.me/GayBBS_bot?start=gate_test"}).url,"https://t.me/GayBBS_bot?start=gate_test");
assert.equal(fn({text:"a",url:"https://t.me/GayBBS_bot?start=online_test"}).url,"https://t.me/GayBBS_bot?start=online_test");
assert.throws(()=>fn({text:"a",url:"https://t.me/GayBBS_bot?start=invalid"}),/STARTLESS_REPEATED_START_LINK_FORBIDDEN/);
assert.equal(fn({text:"a",url:"https://t.me/CreateVdobot?start=creator"}).url,"https://t.me/CreateVdobot");
console.log("STARTLESS_ISOLATED_PUBLIC_BUTTON_BEHAVIOR=PASS");
' < deploy/state/startless-pr71-stage/gaybbs.mjs
